import os
import json
from typing import Any, Dict

from openai import OpenAI


def extract_receipt_structured(receipt_text: str) -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt using OpenAI's hosted API.
    Returns a normalized dictionary.
    """
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

    schema = {
        "type": "object",
        "properties": {
            "merchant": {"type": ["string", "null"]},
            "tax": {"type": ["number", "null"]},
            "total": {"type": ["number", "null"]},
            "items": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "name": {"type": ["string", "null"]},
                        "quantity": {"type": ["number", "null"]},
                        "unit_price": {"type": ["number", "null"]},
                        "amount": {"type": ["number", "null"]},
                    },
                    "required": ["name", "quantity", "unit_price", "amount"],
                    "additionalProperties": False,
                },
            },
        },
        "required": ["merchant", "tax", "total", "items"],
        "additionalProperties": False,
    }

    prompt = (
        "Extract structured data from the following receipt text. "
        "Return only JSON matching the schema.\n\n"
        f"Receipt text:\n{receipt_text}"
    )

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=prompt,
        text={
            "format": {
                "type": "json_schema",
                "name": "receipt_extraction",
                "schema": schema,
                "strict": True,
            }
        },
    )

    output_text = response.output_text
    data = json.loads(output_text)

    return {
        "merchant": data.get("merchant"),
        "tax": data.get("tax"),
        "total": data.get("total"),
        "items": data.get("items", []),
    }
